local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[1448] = { title = "Auf der Suche nach dem Tempel", description = "Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, $C.\n\nDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!\n\nAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.\n\nMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.\n\nHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.", objectives = "Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1449] = { title = "Ins Hinterland", description = "Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.\n\nIch reiste zu dem berühmten Greifenhorst bei Aerie Peak im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf ...\n\nDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.\n\nBegebt Euch dorthin und sucht nach Falstad Wildhammer.\n\nWir müssen herausfinden, was dem Piloten zugestoßen ist.", objectives = "Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1450] = { title = "Greifenmeister Talonaxe", description = "Ihr seid also nur ein $gbesserer Botenjunge:besseres Botenmädchen; für einen alten Tattergreis der Forscherliga, hm?\n\nHört mir gut zu, $C. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Talonaxe aus? Ja?\n\nWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.\n\nUnd jetzt trollt Euch.", objectives = "Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1451] = { title = "Rhapsody-Shindigger", description = "Rhapsody fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.\n\nAber der alte Shindigger brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsody.\n\nDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.\n\nZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet ...", objectives = "Sucht Rhapsody Shindigger im Hinterland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1452] = { title = "Rhapsodys Kalimdor-Cocktail", description = "Hicks!\n\nDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!\n\nWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!\n\nIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.\n\nMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...\n\nEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!", objectives = "Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1453] = { title = "Die Geschäfte der Wiederholer in Desolace", description = "Es gibt Arbeit in Desolace, $n. Das ist ein grässlicher Ort, beschmutzt von Zentauren und anderer Unbill. Aber wenn Ihr eine Woche ehrlicher Arbeit sucht, dann geht dorthin, besucht Kreldig Ungor und sagt ihm, ich hab Euch geschickt.\n\nIhr findet ihn an der Nijelspitze - dem gemütlichen kleinen Lager in den Bergen des nördlichen Desolace. Haltet Euch einfach ostwärts, wenn Ihr vom Steinkrallengebirge kommt. Man übersieht es leicht, also seid wachsam.", objectives = "Sprecht mit Kreldig Ungor in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1454] = { title = "Karnitols Schiffbruch", description = "Mein erster Auftrag betrifft den Magier Karnitol - eine Art Edelmann in Stormwind. Offenbar wurde sein Schiff vor der Küste im Nordwesten von Meeresriesen angegriffen. Er und seine Gefolgsleute versuchten, eine seiner wertvolleren Truhen an Land zu bringen, aber als die Meeresriesen in Schwärmen angriffen, beschloss er, sie aufzugeben und sich und seine Gefolgsleute in Sicherheit zu teleportieren.\n\nEr möchte, dass wir die Truhe samt ihrem Inhalt finden und zu ihm nach Stormwind bringen.", objectives = "Sucht Karnitols Truhe in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1455] = { title = "Karnitols Schiffbruch", description = "Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.\n\nIhr werft einen Blick in die Truhe und stellt fest, dass sie leer ist.\n\nDa Ihr nicht wisst, was Ihr sonst tun sollt, klappt Ihr die Truhe zu und rüstet zum Aufbruch. Kreldig wird enttäuscht sein.", objectives = "Kehrt zu Kreldig Ungor in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1456] = { title = "Karnitols Schiffbruch", description = "Faszinierend.\n\nVielleicht besteht ja doch noch Hoffnung.\n\nAn derselben Küste, aber viel weiter nördlich, nahe der Insel Ranazjar, liegen Ruinen der Nachtelfen auf dem Grund des Meeres. Ein Stamm von Naga, die Zackenkämme, sind dort zu Hause. Das dürfte unsere beste Chance sein.\n\nWenn ein Kundschaftertrupp sich so weit in den Süden wagte, müssen sie sehr mächtig sein. Wenn Ihr Kanitols Habseligkeiten finden wollt, würde ich mit den mächtigeren Naga anfangen: den Gezeitenjägern oder den Meerhexen.", objectives = "Sucht Karnitols Ranzen und bringt ihn zu Kreldig Ungor in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1457] = { title = "Karnitols Schiffbruch", description = "Bringt Karnitols Sachen zu Roetten in Ironforge, er wird Euch die gute Arbeit wohl vergelten.\n\nHaha, wenn Ihr nicht aufpasst, wird er so zufrieden sein, dass er Euch bittet, als Festangestellter bei uns zu bleiben.\n\nWieder einmal gut gemacht, $N.\n\nSeid auf dem Rückweg vorsichtig und lasst Euch nicht zu viel Zeit - Karnitol ist nicht der Geduldigste, aber dennoch höchst großzügig.", objectives = "Bringt Karnitols Ranzen zu Roetten Stonehammer in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1458] = { title = "Reagenzien für die Wiederholer AG", description = "Zu meinen Pflichten hier gehört, Reagenzien für Leftwitch zu beschaffen, einen Gnomen-Magier in Kharanos. Roetten glaubt, das sei ein Kinderspiel, da wir ohnehin schon hier draußen sind. Ihm ist es gleich, dass wir auch so schon unterbesetzt sind.\n\nDie ersten paar Gegenstände auf seiner Liste sollten leicht zu beschaffen sein, und für alle, die mir helfen, springt eine satte Belohnung raus.\n\nIch brauche einige Hörner und Klauen von den Satyrn der Zornsäer östlich von hier. Bringt sie mir, dann nehmen wir uns den Rest der Liste vor.", objectives = "Bringt 10 Zornsäerklauen und 10 Zornsäerhörner zu Kreldig Ungor in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1459] = { title = "Reagenzien für die Wiederholer AG", description = "Als Nächstes steht auf Leftwitchs Liste... mal sehen... hmm. Oh, da haben wir es.\n\nRecht einfach, aber mit sehr expliziten Anweisungen. Er braucht Gift von den Skorpashi und Bälge von Kodos. Im Kleingedruckten steht, beide müssen von bestimmten Kreaturen sein: Das Gift soll von irgendeinem Skorpashi stammen und der Balg muss von einem gealterten Kodo sein, aber keinem sterbenden oder uralten.\n\nMagier, ich sage Euch, was die so alles wollen... abartig.", objectives = "Bringt 7 Phiolen Skorpashigift und 3 Bälge von gealterten Kodos zu Kreldig Ungor in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1462] = { title = "Erdsapta", description = "", objectives = "Sprecht mit der Seherin Ravenfeather wegen eines weiteren Erdsaptas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1463] = { title = "Erdsapta", description = "", objectives = "Sprecht mit Canaga Earthcaller wegen eines weiteren Erdsaptas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1464] = { title = "Feuersapta", description = "", objectives = "Sprecht mit Telf Joolam wegen eines weiteren Feuersaptas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1465] = { title = "Vahlarriels Suche", description = "Als Ihr Eure Suche nach dem Wagen fortsetzt, findet Ihr nicht nur einen Anhänger, sondern auch Fußspuren, die in Richtung Süden führen. In der Ferne seht Ihr Rauch von einem großen Fort aufsteigen. Der Rauch stammt von einem Lagerfeuer, nicht von brennenden Gebäuden. Euer Instinkt sagt Euch, dass die Malems, wenn sie noch leben, in diese Richtung gebracht wurden.\n\nIhr seid der Ansicht, dass Vahlarriel an der Nijelspitze nicht nur den Anhänger sehen sollte, den Ihr gefunden habt, sondern auch von den Lebenszeichen im Süden wissen sollte.", objectives = "Kehrt mit dem Malem-Anhänger zu Vahlarriel Demonslayer in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1466] = { title = "Reagenzien für die Wiederholer AG", description = "Das ist der letzte Gegenstand und ganz ehrlich, er ist nicht schön. Ich gehe auch davon aus, dass Ihr dafür etwas länger braucht als für die anderen Gegenstände.\n\nDoch genug der Warnungen, fangen wir an. Leftwitch sagt, er braucht Folgendes: zehn Gehirne, entweder von Manafressern, Magierjägern oder Leyjägern, zehn Netherflügel von einer Nethermaid, -Schwester oder -Zauberhexerin. Und... zehn Phiolen Verdammniswächterblut von einem Captain oder Lord der Verdammniswächter.\n\nGanz einfach, hm? Tja... ich hätte Verständnis dafür, wenn Ihr dies ausschlagen wollt.", objectives = "Bringt 10 Teufelshundgehirne, 10 Netherflügel und 10 Phiolen Verdammniswächterblut zu Kreldig Ungor in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1467] = { title = "Reagenzien für die Wiederholer AG.", description = "Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Ironforge zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Leftwitchs Päckchen vom Hals hat. Gebt ihm das, es müsste genügen, damit Ihr Euren Anteil bekommt.\n\nKeine Bange, ich werde trotzdem ein gutes Wort für Euch einlegen, wenn ich zurück bin. Ich sollte nicht mehr lange in Desolace bleiben müssen.", objectives = "Bringt Leftwitchs Päckchen zu Roetten Stonehammer in Ironforge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1468] = { title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch $n, benutzt die Pfeife und trefft Euren Schützling.", objectives = "Benutzt die Pfeife des Menschenwaisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1469] = { title = "Rhapsodys Geschichte", description = "Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!\n\nUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!\n\nJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!", objectives = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1470] = { title = "Der zerrissene Schleier", description = "Seid gegrüßt, Kind. Ich sehe, dass Ihr noch unerfahren in den Dingen der Hexenmeister seid, dass sich die Macht noch Eurem Griff entzieht. Doch ich spüre Euren Eifer zu lernen.\n\nUnd Ihr werdet lernen.\n\nDurch Ignoranz kann man keine Stärke finden. Wissen ist unsere größte Macht. Indem wir es anwenden, können wir die chaotische Magie und die Wesen der Leere kontrollieren und unserem Willen beugen.\n\nIch zeige Euch, wie Ihr einen Diener an Euren Willen bindet, doch zuerst müsst Ihr mir drei Schädel der klappernden Skelette nahe der verlassenen Schmiede bringen.", objectives = "Bringt Venya Marthand 3 Schädel eines klappernden Skeletts.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1471] = { title = "Die Bindung", description = "Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.\n\nMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.\n\nWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.", objectives = "Beschwört mit Hilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halger im Tempel der Verdammten zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1472] = { title = "Verschlinger der Seelen", description = "Ein Sukkubus ist ein Verschlinger von Seelen, Zerstörer von Herzen, Versucher der Menschen. Eine durch und durch böse und engstirnige Kreatur.\n\nOhne Anreiz kann er nicht in unsere Welt gebracht werden.\n\nDoch wir wenden seine eigene Kraft gegen ihn an. Den Herzen guter, reiner oder liebender Männer kann der Sukkubus nicht widerstehen und tritt in unsere Welt herüber. Dann könnt Ihr ihn beherrschen und zu Eurem Eigen machen.\n\nSprecht mit meinem Assistenten Godrick Farsan im Tempel. Er hilft Euch bei der Suche nach einem Köder.", objectives = "Sprecht mit Godrick Farsan im Tempel der Verdammten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1473] = { title = "Kreatur der Leere", description = "Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.\n\nEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.\n\nEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.\n\nLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.", objectives = "Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1474] = { title = "Die Bindung", description = "Benutzt diese Herzen und wirkt einen Zauber am Beschwörungskreis, um eine Tür zu öffnen, durch die der Sukkubus kommen kann. Eure Mächte sind jetzt größer und Ihr werdet sie alle brauchen, um den Sukkubus zu besiegen. \n\nHütet Euch vor seinen Bezauberungen, $n, manch starker Geist wurde schon seinem Willen unterworfen. Wenn er überwunden wurde, kehrt der Sukkubus in die Leere zurück, dann lehre ich Euch den Zauber, um ihn nach Eurem Gutdünken zurückzurufen.", objectives = "Beschwört mit Hilfe der reinen Herzen einen Sukkubus, unterwerft ihn und bringt die reinen Herzen dann zu Carendin Halger im Tempel der Verdammten zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1475] = { title = "Im Tempel von Atal'Hakkar", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, $n.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.", objectives = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Caskbelly in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1476] = { title = "Herzen der Reinen", description = "Männer mit Ehre und Güte? Existiert so ein Mann?\n\nViele Recherchen waren erforderlich, doch durch Geschichten, die ich hörte, konnte ich zwei Männer finden, die genügen sollten.\n\nDer Erste ist Dalin Forgewright, der sich der Fürsorge für die Flüchtlinge von Lordaeron verschrieben hat, die von ihresgleichen am Greymane-Wall verstoßen werden.\n\nDer andere ist Comar Villard, ein Mann, der seiner verlorenen Liebsten treu blieb und im Sumpfland nach Spuren seiner Frau sucht.\n\nBringt ihre Herzen zu Carendin. Doch zuvor möchte ich Euch Eure Opfer zeigen.", objectives = "Bringt die Herzen von Dalin Forgewright und Comar Villard zu Carendin Halgar im Tempel der Verdammten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1477] = { title = "Überaus wichtige Vorräte", description = "Unsere Magier führen Forschungen in der Burg Nethergarde in den Verwüsteten Landen durch, die entscheidend für unser Verständnis der Dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch unsere Nachschubwege nach Nethergarde sind dürftig.\n\nIhr müsst helfen sicherzustellen, dass der Nachschub nach Nethergarde gelangt. Meldet Euch bei Wachhauptmann Sorigal in Dunkelhain und tut, was er verlangt. Diese Aufgabe führt Euch in Feindesland, $n. Macht Euch bereit.", objectives = "Sprecht mit Wachhauptmann Sorigal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1478] = { title = "Halgars Beschwörung", description = "Ah, $n! Carendin Halgar ließ mich soeben wissen, dass er Euch für weitere Ausbildung sehen möchte.\n\nIhr solltet stolz auf Euch sein, $n Es kommt nicht jeden Tag vor, dass Meister Halgar persönlich einen jungen Hexenmeister unterrichtet.\n\nIhr findet ihn im Magieviertel von Undercity nahe des Tempels der Verdammten.", objectives = "Sprecht mit Carendin Halgar in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1479] = { title = "Der Baum der Ewigen", description = "Ich habe Geschichten von den Nachtelfen gehört, darüber, dass sie ihre Bank in einen Baum gebaut haben, der aber wie ein Bär aussieht. Das ist so cool! Nachtelfen sind niedlich, wie sie die Natur lieben und so, aber Bären sind der Hammer!\n\nWürdet Ihr bitte mit mir den Bärenbaum in Darnassus angucken gehen? Es gibt ein Boot, das uns ganz in die Nähe dorthin bringt und es wird auch bestimmt nicht lange dauern. Bitte, bitte, bitte!", objectives = "Begleitet Euren Schützling zur Bank in Darnassus. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1480] = { title = "Der Verderber", description = "Die zerrissene Haut riecht verfault und ist erstaunlich geschmeidig für etwas, das so trocken und zerbrechlich wirkt.\n\nAls Ihr sie aufrollt, könnt Ihr deutlich die roten Zeichen einer Art Sprache auf der einen Seite erkennen. Am unteren Ende der Haut befindet sich ein sehr deutliches Symbol, das Ihr für eine Art Unterschrift haltet.\n\nVielleicht könnte Maurin Euch mehr darüber erzählen?", objectives = "Bringt die geschundene Dämonenhaut nach Desolace zu Maurin Bonesplitter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1481] = { title = "Der Verderber", description = "Ich denke, mit den entsprechenden Reagenzien kann ich diesen Dämonenlord finden.\n\nWenn er wirklich so mächtig ist, wie ich vermute, brauche ich gesammelte Gegenstände von tödlichen Kreaturen. Doch Ihr handelt im Namen des Kriegshäuptlings, daher werdet Ihr die Aufgabe gewiss übernehmen.\n\nAls Erstes muss ich jeden Schutzzauber brechen, den er gegen Wahrsagen hat. Daher brauche ich den Skalp eines Satyrs... aber nicht den eines beliebigen Satyrs. Der Skalp muss von einem Schattenpirscher der Zornsäer stammen.\n\nSucht in den antiken Ruinen nordöstlich von Desolace nach ihnen.", objectives = "Bringt Maurin Bonesplitter in Desolace einen Schattenpirscherskalp.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1482] = { title = "Der Verderber", description = "Ein Orakelkristall wäre genau richtig. Die Naga stellen sie her, damit ihre Orakel sie benutzen können.\n\nNordwestlich von hier liegt ein großes Korallenriff vor der Küste, das die Naga als ihre Heimat nutzen, da es so nahe am Ufer liegt. Dort könnt Ihr ihre Orakel finden. Die Zackenkammnaga sind tödlich und reagieren ungnädig auf Euer Eindringen, seid daher vorsichtig und eilt Euch.\n\nWenn Ihr zurückkehrt, suchen wir diesen Dämonenlord Azrethoc.", objectives = "Bringt Maurin Bonesplitter in Desolace einen Orakelkristall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1483] = { title = "Ziz Fizziks", description = "Die Venture Company stahl viele meiner besten Goblin-Denker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.\n\nVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Wrenchwhistle ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.\n\nVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.", objectives = "Sprecht mit Ziz Fizziks bei der Scherwindklippe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1484] = { title = "Der Verderber", description = "Diese Kreatur ist weitaus gefährlicher als ich dachte. Zweifellos stellt Takata in Frage, dass ich so einer Kreatur gewachsen bin, und es würde ihn in seiner Ehre kränken, wenn er nicht wüsste, was gerade passierte.\n\nSprecht mit dem Schwertkämpfer, sagt ihm, Ihr seid bereit, den Dämon zu erschlagen, wenn er es erlaubt, aber bedrängt ihn nicht zu sehr. Es ist besser, wenn er denkt, dass es seine Idee war.", objectives = "Sprecht mit Takata Steelblade in Desolace.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1485] = { title = "Üble Familiare", description = "Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.\n\nDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.\n\nBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der schändlichen Familiare aus der Höhle im Nordosten.", objectives = "Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1486] = { title = "Deviatbälge", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen unter uns hinab und holt einige Deviatschuppen.", objectives = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1487] = { title = "Ausrottung der Deviat", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.\n\nNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.\n\nWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.\n\nWagt Euch in die Höhlen, $n, und löscht die Deviatbrut aus.", objectives = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1488] = { title = "Der Verderber", description = "Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden. Besonders wenn er versucht, Einfluss über die Burning Blade zu bekommen, um seine Ziele voranzutreiben.\n\nIhr habt schon gezeigt, dass Ihr den Kriegshäuptling unterstützen möchtet. Ich verlasse mich darauf, dass Ihr eine Truppe zusammenstellt, die den Dämonenlord und seinen Hexenmeisterdiener besiegt.\n\nWenn Ihr bereit seid, geht direkt nach Süden und kehrt zu mir zurück, wenn die Bedrohung beseitigt wurde.", objectives = "Besiegt Lord Azrethoc und Jugkar Grim'rod. Kehrt dann zu Takata Steelblade in Desolace zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1489] = { title = "Hamuul Runentotem", description = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.\n\nDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runetotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.\n\nIhr findet ihn in Thunder Bluff auf der Anhöhe der Ältesten.", objectives = "Sprecht mit Hamuul Runetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1490] = { title = "Nara Wildmähne", description = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.\n\nIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.\n\nSprecht mit Nara. Sie ist in jenem Zelt da drüben.", objectives = "Sprecht mit Nara Wildmane.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1491] = { title = "Klugheitstränke", description = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!\n\nEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!\n\nIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", objectives = "Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1492] = { title = "Werftmeister Dizzywig", description = "Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratchet zu bringen, und die letzte Karawane ist schon aufgebrochen.\n\nKönntet Ihr sie bitte freundlichst zu Werftmeister Dizzywig bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.", objectives = "Bringt die gesicherte Kiste zu Werftmeister Dizzywig in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1498] = { title = "Weg der Verteidigung", description = "Als Krieger ist eine unserer wichtigsten Aufgaben... der Schutz. Wir sind der Schild der Horde und sorgen für die Sicherheit unserer schwächeren Brüder. Wenn Ihr Euch bei uns einreihen möchtet, müsst Ihr mir Eure Tauglichkeit beweisen.\n\nGeht zum Donnergrat in Durotar, wo die Blitzechsen und Donnerechsen hausen. Jagt die Bestien! Zeigt mir, dass Ihr härter als sie seid! Trotzt ihren Angriffen und bringt mir einen Stapel ihrer versengten Schuppen als Beweis.\n\nGelingt Euch das, unterrichte ich Euch.", objectives = "Bringt 5 versengte Schuppen zu Uzzek im Farwatch-Posten im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1499] = { title = "Üble Familiare", description = "Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die schändlichen Familiare gekämpft habt.\n\nIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.", objectives = "Sprecht mit Zureetha Fargaze.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1501] = { title = "Kreatur der Leere", description = "So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.\n\nEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.\n\nAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Burning Blade gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.", objectives = "Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1502] = { title = "Thun'grim Brandblick", description = "Es ist wichtig, dass ein Krieger eine hochwertige Waffe hat. Und wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist das Thun'grim Firegaze. Er ist ein Einsiedler, der auf den Hügeln östlich von Crossroads haust.\n\nWenn Ihr eine Waffe sucht, Krieger, dann solltet Ihr Euch an Thun'grim wenden. Um ihn zu finden reist Ihr zuerst nach Crossroads im Westen und wendet Euch dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel.", objectives = "Sprecht mit Thun'grim Firegaze im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1503] = { title = "Geschmiedeter Stahl", description = "Ich gebe Euch eine Waffe, $N, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Grimmhauer von Nordwesten in mein Lager. Sie wollten nicht mit mir kämpfen, wissen aber, wie schlecht es um mein Augenlicht bestellt ist. Einige lenkten mich durch Schnauben ab, während die anderen mich bestahlen. Diese Feiglinge!\n\nSie nahmen eine Eisentruhe mit, in der sich Schmiedestahlbarren befanden. Wenn Ihr sie wiederbeschaffen könnt, bekommt Ihr die Waffe, die Ihr sucht.\n\nSucht im Stacheleberlager nach der Eisentruhe und bringt die Schmiedestahlbarren zurück.", objectives = "Bringt die Schmiedestahlbarren zu Thun'grim Firegaze im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1504] = { title = "Die Bindung", description = "Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Fireblades Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.\n\nIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.", objectives = "Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1505] = { title = "Veteran Uzzek", description = "Die Horde ehrt ihre Krieger, da ihre Kraft außer Frage steht. Doch die wahrhaft großen Helden sind auch große Schüler.\n\nSucht nach Uzzek. Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst. Ihr findet ihn südlich des Farwatch-Posten, der Orc-Garnison an der Grenze von Brachland und Durotar im Osten.", objectives = "Sprecht mit Uzzek im Farwatch-Posten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1506] = { title = "Gan'ruls Beschwörung", description = "Ihr da. $n, richtig?\n\nIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.\n\nMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.", objectives = "Sprecht mit Gan'rul Bloodeye in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1507] = { title = "Verschlinger der Seelen", description = "Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sukkubus zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.\n\nEin Sukkubus kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.\n\nEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.", objectives = "Sprecht mit Cazul in der Kluft der Schatten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1508] = { title = "Der blinde Cazul", description = "Hmmm... Aber natürlich seid Ihr nicht gekommen, um deshalb mit mir zu sprechen.\n\nWenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.\n\nHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, $n, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.\n\nGeht zu ihr.", objectives = "Sprecht mit Zankaja in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1509] = { title = "Neuigkeiten von Dogran", description = "Dogran, mein Gefährte, wurde jüngst zum Dienst nach Crossroads geschickt. Es war eine Beförderung und er war sehr stolz.\n\nIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.\n\nSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...\n\nVielleicht könntet Ihr nach Crossroads gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.", objectives = "Sprecht mit Gazrog in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1510] = { title = "Neuigkeiten von Dogran", description = "Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.\n\nSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.", objectives = "Sprecht mit Ken'zigla am Malaka'jin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1511] = { title = "Ken'ziglas Trunk", description = "Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.\n\nDa habt Ihr ihn, $n. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.\n\nWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.", objectives = "Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1512] = { title = "Die Liebesgabe", description = "Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.\n\nLasst mich allein, $n. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.\n\nUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.", objectives = "Bringt den schmutzverkrusteten Anhänger zu Gan'rul Bloodeye in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1513] = { title = "Die Bindung", description = "Bringt dies zum Beschwörungskreis in Neerus Zelt, $n. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.\n\nWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.", objectives = "Beschwört mit Hilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Bloodeye in Orgrimmar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1514] = { title = "Verderbte Windblüte", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1515] = { title = "Dograns Gefangenschaft", description = "Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.\n\nDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.\n\nViel Glück.", objectives = "Bringt Ken'ziglas Trunk zu Dogran im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1516] = { title = "Ruf der Erde", description = "Die Zeit ist gekommen, junger $C. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.\n\nDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.\n\nSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.", objectives = "Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1517] = { title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.\n\nDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo ... vergesst das nicht.\n\nBesucht den Geisterfelsen südwestlich von hier ... er befindet sich am Ende des verborgenen Pfades. Trinkt Euer Sapta dort und ... tja, Ihr werdet schon sehen.", objectives = "Sucht den Geisterfelsen und trinkt das Erdsapta.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1518] = { title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Earthcaller. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.\n\nHabt Geduld, $N. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", objectives = "Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1519] = { title = "Ruf der Erde", description = "Die Zeit ist gekommen, $C. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.\n\nDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.\n\nSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.", objectives = "Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1520] = { title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.\n\nDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.\n\nSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.", objectives = "Sucht den Kodofels und trinkt das Erdsapta.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1521] = { title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu der Seherin Ravenfeather. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.\n\nHabt Geduld, $N. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", objectives = "Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1522] = { title = "Ruf des Feuers", description = "Feuer sei mit Euch, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen der Erde und scheint mir bereit, mit Kranal zu sprechen.\n\nKranal lebt nördlich von Crossroads im Brachland. Er kennt sich mit den Elementen aus und kann Euch was übers Feuer beibringen ... wenn Ihr denkt, dass Ihr bereit seid.\n\nEr ist leicht zu finden, geht nur nicht zu weit. Wenn Ihr zu weit geht, seid Ihr plötzlich im Elfenland.", objectives = "Sucht Kranal Fiss im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1523] = { title = "Ruf des Feuers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", objectives = "Sucht Kranal Fiss im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1524] = { title = "Ruf des Feuers", description = "Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.\n\nAm Südstromfluss in Durotar, vor dem großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht ... den Schrein der schlafenden Flamme.\n\nBringt ihm diese Fackel ... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.", objectives = "Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1525] = { title = "Ruf des Feuers", description = "Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.\n\nZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.\n\nIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Grimmhauer im östlichen Brachland mit sich führen.\n\nDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Burning Blade. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.", objectives = "Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1526] = { title = "Ruf des Feuers", description = "Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.\n\nSchlagt ihn schnellstens nieder, $n, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.", objectives = "Besiegt die geringe Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1527] = { title = "Ruf des Feuers", description = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.\n\nAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.", objectives = "Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1528] = { title = "Ruf des Wassers", description = "Wasser sei in Eurer Zukunft, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen des Feuers und scheint mir bereit, mit Islen zu sprechen.\n\nIslen lebt an der Küste des Brachlandes. Wenn Ihr am Ufer des Südstroms nach Süden geht, könnt Ihr sie gar nicht verfehlen ... achtet auf den großen Hai! Sie kennt sich mit den Elementen aus und kann Euch etwas übers Wasser beibringen ... wenn Ihr denkt, dass Ihr bereit seid.\n\nSie ist leicht zu finden, geht nur nicht zu weit nach Süden ... sie ist gleich hinter Ratchet.", objectives = "Sucht Islen Waterseer im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1529] = { title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, $N. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, $N.", objectives = "Sucht Islen Waterseer im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1530] = { title = "Ruf des Wassers", description = "Wenn Ihr eine Lektion über Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt.\n\nSeine Macht fließt, erodiert und reinigt alle Arten von Dingen. Seine Fähigkeit zu heilen und zu regenerieren ist unvergleichlich, jedoch nur, wenn es rein ist.\n\nWenn Ihr begreift, dass verunreinigtes Wasser alles verheeren kann, was es berührt, werdet Ihr schätzen lernen, wie lebenswichtig dieser Rohstoff ist.\n\nWenn Ihr das Wassersapta möchtet, sucht Brine tief im Südlichen Brachland. Ihr Heim wird unablässig von den dortigen Stachelebern heimgesucht.", objectives = "Sucht Brine im südlichen Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1531] = { title = "Ruf der Luft", description = "Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Cloudseer in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.\n\nGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.", objectives = "Sucht Prate Cloudseer in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1532] = { title = "Ruf der Luft", description = "Die Winde von Kalimdor wehen Euch entgegen und Ihr sollt zu den Mächtigsten unserer $gBrüder:Schwestern; gehören. Ich sehe mit Stolz, dass Ihr so weit gekommen seid und so eine viel versprechende Zukunft habt.\n\nDas Luftelement ist schwer zu kontrollieren, doch ich vertraue darauf, dass Eure Fertigkeiten alle Hindernisse überwinden, die Euch den Weg versperren.\n\nGeht zum äußersten Südrand des Brachlandes und betretet Tausend Nadeln. Dort, weit im Osten, werdet Ihr Prate Cloudseer finden. Sie wird Euch mehr beibringen.", objectives = "Sucht Prate Cloudseer in Tausend Nadeln.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1534] = { title = "Ruf des Wassers", description = "Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, die die Nachtelfen Ashenvale nennen. Sie liegen weit nördlich des Brachlandes.\n\nWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und Ashenvale trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.\n\nBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.", objectives = "Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen in Ashenvale und kehrt zu Brine im Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1535] = { title = "Ruf des Wassers", description = "Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.\n\nWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.", objectives = "Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1536] = { title = "Ruf des Wassers", description = "Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge von Hillsbrad. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.\n\nDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.\n\nBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.", objectives = "Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1558] = { title = "Der Steinwerkdamm", description = "In der Nähe von Eisenschmiede, wo all die Zwerge und Gnome leben, gibt es einen Ort namens Loch Modan und die Zwerge haben da einen grooooßen Staudamm gebaut. Ich habe gehört, dass ist eines von den größten Dingen, die je gebaut wurden. Wow!\n\nKönnt Ihr mir den Damm in Loch Modan zeigen, bitte?! Ich glaube der heißt Stein... äh... Steinwerkdamm? Er ist riesig, so viel ist klar. Ich würde so gerne auf den großen Wasserfall heruntersehen. Ich verspreche, mich auch nicht zu weit vorzulehnen.", objectives = "Begleitet Euren Schützling zum Steinwerkdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1559] = { title = "Blitzstrahlbombenanleitung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1560] = { title = "Toogas Bitte", description = "Ich habe mich vollkommen verirrt!\n\nTorta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein.\n\nWürdet Ihr so freundlich sein, mich zu Torta zurückzuführen? Sie wartet südlich von Steamwheedle auf mich.", objectives = "Zeigt Tooga den Weg zurück zu seiner Frau Torta.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1578] = { title = "Nachschub für die Front", description = "Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.\n\nDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.\n\nThorvald ist im südlichem Wachturm des Loch Modan.", objectives = "Bringt 6 Kupferäxte und 6 Kupferne Kettengürtel zu Thorvald im südlichen Wachturm des Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1579] = { title = "Klemm-Muffen", description = "Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Ironforge nicht!\n\nDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemm-Muffen über Bord fallen! Ich brauche meine Klemmmuffen!\n\nIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...", objectives = "Bringt 8 Klemm-Muffen zu Wizbang Cranktoggle in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1580] = { title = "Elektropeller", description = "Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, $n?\n\nEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!\n\nIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...", objectives = "Bringt 12 Elektropeller zu Wizbang Cranktoggle in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1581] = { title = "Elixiere für die Bladeleafs", description = "Unser Kräuter- und Alchimie-Laden floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.\n\nKönnt Ihr uns helfen?\n\nWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse rare Kräuter, die Euch nützlich sein könnten.", objectives = "Bringt 6 Elixiere Löwenkraft und 2 Elixiere der schwachen Verteidigung zu Syral Bladeleaf in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1582] = { title = "Mondscheinweste", description = "Wir in Darnassus, besonders wir Handwerker, sind sehr beschäftigt. Junge Abenteurer brennen darauf, sich in der Wildnis zu beweisen, und benötigen unablässig Nachschub.\n\nWenn Ihr mir helft, meine Bestellungen an Lederwaren zu erfüllen, kann ich Euch vielleicht eine hochentwickelte Technik der Lederverarbeitung beibringen.", objectives = "Bringt 1 geprägten Lederhandschuh, 5 geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1598] = { title = "Der gestohlene Foliant", description = "Ihr da! $n, richtig?\n\nIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.\n\nIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.\n\nEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.\n\nEines davon war ein Buch, das ich selbst wollte, \"Die Macht der Leere\". Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.", objectives = "Holt \"Die Macht der Leere\" für Drusilla La Salle zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1599] = { title = "Anfänge", description = "Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.\n\nKeine Bange, ich mache Euch keinen Vorwurf.\n\nDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.\n\nBringt mir drei Federglücksbringer von den Novizen der Frostmane aus der Höhle im Südwesten.", objectives = "Bringt 3 Federglücksbringer zu Alamar Grimm in Anvilmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1618] = { title = "Die Aufrüstung im Rotkammgebirge", description = "Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!\n\nDas Rotkammgebirge wird immer wieder von den Blackrockorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Osgood, Euch den einen oder anderen Trick beibringen.", objectives = "Tormus Deepforge möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Osgood ins Rotkammgebirge bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1638] = { title = "Die Ausbildung eines Kriegers", description = "Ihr habt Euch als fähiger Krieger erwiesen, $N. Aber Ihr seid noch jung und müsst noch viel lernen.\n\nSprecht mit Harry Burlguard... er ist meist in der Taverne Zum pfeifenden Schwein in der Altstadt von Stormwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.", objectives = "Sprecht mit Harry Burlguard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1639] = { title = "Bartleby der Trunkenbold", description = "Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.\n\nSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.\n\nHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.", objectives = "Sprecht mit Bartleby.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1640] = { title = "Besiegt Bartleby", description = "Ihr wollt was??? Ihr seid verrückt!\n\nWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", objectives = "Besiegt Bartleby und redet dann mit ihm.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1641] = { title = "Der Foliant der Offenbarung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1642] = { title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1643] = { title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, $N, besteht darin, jemanden hier in Stormwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.", objectives = "Sucht im Handelsdistrikt von Stormwind nach Stephanie Turner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1644] = { title = "Der Foliant der Offenbarung", description = "Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.\n\nMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.\n\nWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, $n.\n\nWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.", objectives = "Bringt 10 Stück Leinenstoff zu Stephanie Turner in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1645] = { title = "Der Foliant der Offenbarung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1646] = { title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1647] = { title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, $N, ist es, jemanden hier in Ironforge zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.", objectives = "Sucht im äußeren Ring von Ironforge nach John Turner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1648] = { title = "Der Foliant der Offenbarung", description = "Meine Frau und ich führen das Waisenhaus in Stormwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Ironforge und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.\n\nDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.\n\nKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.", objectives = "Bringt 10 Stück Leinenstoff zu John Turner in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1649] = { title = "Der Foliant der Ehre", description = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.\n\nDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1650] = { title = "Der Foliant der Ehre", description = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.\n\nAm äußersten Ende von Longshore in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stilwells. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Ironforge gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.\n\nEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.", objectives = "Sucht Daphne Stilwell in Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1651] = { title = "Der Foliant der Ehre", description = "Ich wette, die kommen bald wieder, also macht Euch bereit.\n\nIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.\n\nIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.\n\nBittet das Licht um jeden erdenklichen Segen, denn ... habt Ihr das gehört? Ich glaube, sie kommen.\n\nWir beziehen Position beim Haus!", objectives = "Verteidigt Daphne Stilwell vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1652] = { title = "Der Foliant der Ehre", description = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.\n\nEr wird eine Nachricht nach Ironforge schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.\n\nOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1653] = { title = "Die Prüfung der Rechtschaffenheit", description = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.\n\nJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.\n\nEr müsste noch in Ironforge sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.", objectives = "Sprecht mit Jordan Stilwell in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1654] = { title = "Die Prüfung der Rechtschaffenheit", description = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.\n\nIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, $C?", objectives = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1655] = { title = "Bailors Erzlieferung", description = "Ach, Ihr habt mich erschreckt, $G Mann:Frau;! Seht Ihr nicht, dass ich nachdenke?\n\nWie war das? Jordans Lieferung... für Ironforge. Ahhh, ja, ich weiß, wovon Ihr sprecht. Oger der Mo'grosh haben die Erzlieferung meines alten Freundes gestohlen. Die Karawane war auf dem Weg vom Sumpfland hierher und geriet in einen Hinterhalt. Die Wache, die den Angriff überlebte, starb vor wenigen Tagen - der Heiler kam nicht schnell genug hin.\n\nWenn Ihr die Lieferung wollt, müsst Ihr über den Loch nach Nordosten. Dort muss sie irgendwo sein.", objectives = "Bringt Jordans Erzlieferung zu Bailor Stonehand am Loch Modan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1656] = { title = "Eine unvollendete Aufgabe", description = "$N, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Mesa noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus von Bloodhoof abzuliefern.\n\nIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?\n\nDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.", objectives = "Bringt das Bündel Felle zu Gastwirt Kauth in Bloodhoof.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1657] = { title = "Die Verpestung von Southshore", description = "Feiert die Schlotternächte mit Stil... bereitet unseren Feinden in Southshore Kummer!\n\nNehmt eine dieser speziell angefertigten Stinkbomben. Sie sind mit einem derartig furchtbaren Schrecken gefüllt, dessen Geruch kein Mensch - oder anderes Wesen mit schwachem Gemüt - ertragen kann. Ihr müsst die Stinkbombe direkt ins Herz von Southshore werfen, damit sie richtig wirken kann. Seid also auf eine Auseinandersetzung mit der Allianz gefasst!\n\nSolltet Ihr diese Aufgabe bewältigt haben, kehrt zu mir zurück... es ist ein Beitrag zu unserer Befreiung!", objectives = "Werft drei Stinkbomben der Verlassenen ins Herz von Southshore in Hillsbrad und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1658] = { title = "Bespitzelt das Fest des Weidenmanns", description = "Ich brauche mutige Freiwillige, die nach Tirisfal ziehen und das Fest des Weidenmanns auskundschaften. Ich möchte nicht lügen - diese Mission ist äußerst gefährlich. Die Wachen des Fests werden besonders bösartig sein. Trotzdem, wir müssen in Erfahrung bringen wie groß das Fest dieses Jahr ist und wieviel Schaden die Verlassenen dieses Mal während der Schlotternächte anrichten.\n\nSolltet Ihr dabei sein, dann geht nach Tirisfal und kundschaftet das Fest aus. Kehrt mit den Informationen zu mir zurück und ich werde für eine angemessene Belohnung sorgen.", objectives = "Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Sergeant Hartman in Southshore zurück, sobald Ihr Eure Mission erfüllt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1661] = { title = "Der Foliant des Adels", description = "Ich grüße Euch erneut, $n. Ich bin stolzer als jemals zuvor, Euch $g Bruder:Schwester; nennen zu können - Euer Engagement ist ein Tribut an uns alle.\n\nDie Zeit ist für mich gekommen, Euch ein wunderbares Geschenk zu übergeben. Wisset aber, dass ich es Euch fürs Erste zwar frei gebe, später jedoch, falls die Zeit es erlaubt, wird dies eine viel größere Herausforderung für alle Paladine sein, die sich dazu entscheiden, meinen Auftrag anzunehmen.\n\nSprecht erneut mit mir und ich werde Euch einen großen Segen gewähren.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1665] = { title = "Bartlebys Becher", description = "Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.", objectives = "Bringt Bartlebys Becher zu Burlguard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1666] = { title = "Marschall Haggard", description = "Ihr habt einige Kampftechniken gelernt, braucht aber noch eine anständige Waffe. Ich wette, Marshal Haggard könnte Euch helfen, wenn Ihr mit ihm sprecht.\n\nMarshal Haggard lebt in einem Anwesen im Wald von Elwynn, beim Holzfällerlager des Osttals. Er ist jetzt im Ruhestand, hat aber in seiner Laufbahn eine Menge Ausrüstung gesammelt.\n\nLasst ihn wissen, dass ich Euch geschickt habe, und mit etwas Glück hat er eine Waffe für Euch übrig.", objectives = "Sprecht mit Marshal Haggard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1667] = { title = "Stumpfzahn Jack", description = "Burlguard hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch...\n\nVor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack. Es war dunkel und er trug ein Stormwindwams, daher dachte ich, er sei Marshal Dughan. Er sagte, er braucht meinen alten Marshalstern aus Stormwind und ich gab ihm diesen... dann lachte er und lief weg, ehe ich ihn packen konnte!\n\nBringt mir meinen Stern! Stumpfzahn Jack hat ihn wahrscheinlich in seinem Lager im Süden versteckt.", objectives = "Holt Marshal Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marshal Haggard zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1678] = { title = "Vejrek", description = "Wenn Ihr es in den Reihen der Krieger zu etwas bringen wollt, müsst Ihr zäh sein. Ich kann Euch neue Kampftechniken beibringen, aber zuvor müsst Ihr mir beweisen, dass Ihr gegen richtige Feinde bestehen könnt.\n\nVejrek ist der härteste Troll, den Ihr in dieser Gegend findet. Ihn müsst Ihr besiegen. Er hat eine Hütte im Vorgebirge südlich der Frostmanehöhle.\n\nBringt mir Vejreks Kopf, dann weiß ich, dass Ihr Mumm habt.", objectives = "Bringt Vejreks Kopf zu Muren Stormpike in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1679] = { title = "Muren Sturmlanze", description = "Hallo, Krieger! Ihr seid viel versprechend, aber dennoch müsst Ihr ein paar Tricks lernen, und Muren Stormpike ist genau der Zwerg, der sie Euch beibringen kann.\n\nIhr findet Muren in der Halle der Waffen im Militärviertel von Ironforge. Sprecht mit ihm, wenn Ihr bereit seid zu lernen, was es heißt, ein Krieger zu sein.", objectives = "Sprecht mit Muren Stormpike.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1680] = { title = "Tormus Tiefenschmied", description = "Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Deepforge. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.\n\nIhr findet Tormus hier in Ironforge bei der großen Schmiede.", objectives = "Sprecht mit Tormus Deepforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1681] = { title = "Ironbands Truppenlager", description = "Mein Mentor Sturgy Ironband hatte ein Lager südlich des Helmsbedsees im östlichen Dun Morogh. Dort lehrte er die Schmiedekunst und er war der Beste.\n\nAber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Meister Ironband nannte es Umbralerz und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande Dunkeleisenzwerge sein Lager an. Sie töteten alle!\n\nBegebt Euch zu Ironbands Lager, $N, und rächt den Tod meines Meisters. Und bringt mir die Ladung Umbralerz, die all das auslöste.", objectives = "Bringt eine Ladung Umbralerz zu Tormus Deepforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1682] = { title = "Waffen aus grauem Eisen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1683] = { title = "Vorlus Elendshuf", description = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.\n\nDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.\n\nSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.\n\nDer Weg zum Mondbrunnen ist gut verborgen, $n, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", objectives = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1684] = { title = "Elanaria", description = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.\n\nDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", objectives = "Sprecht mit Elanaria.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1685] = { title = "Gakins Beschwörung", description = "Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.\n\nIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.\n\nIhr findet ihn im Keller der Taverne Zum geschlachteten Lamm. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.", objectives = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1686] = { title = "Eluras Schemen", description = "Ihr habt viel gelernt, $n. Jetzt fertigen wir Euch eine Waffe an. Die Waffe eines Kriegers.\n\nDazu müsst Ihr nach Dunkelküste reisen.\n\nVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten Eluniterz sanken auf den Meeresgrund.\n\nAls Erstes müsst Ihr den Wächter des Elunits besiegen, Eluras Schemen. Sie war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Besiegt sie, nehmt Ihr das Medaillon ab und sammelt die verlorenen Elunitkisten ein.", objectives = "Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1687] = { title = "Der gruselige Leuchtturm", description = "Abends erzählen uns die Matronen manchmal Gruselgeschichten. Die sind spitze! Einmal haben sie uns von einem Geist erzählt, der in einem Leuchtturm in Westfall spukt. Er soll einmal ein Piratenkapitän gewesen sein, dessen Schiff ihm von anderen Piraten weggenommen wurde. Wow!\n\nKönnen wir uns bitte den Leuchtturm in Westfall anschauen? Ich will nachgucken, ob der Geist des Kapitäns noch immer dort ist! Ich bleibe auch immer nah bei Euch. Ich renn' auch bestimmt nicht weg oder so was.", objectives = "Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1688] = { title = "Surena Caledon", description = "Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!\n\nDas diebische Weib brannte mit einem der Defias durch, Erlan Drudgemoor. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.\n\nIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackwells Kürbisbeet. Bringt wieder, was mir gehört.", objectives = "Beschafft Surenas Halsschmuck für Gakin den Dunkelbinder in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1689] = { title = "Die Bindung", description = "Ihr habt meinen Halsschmuck zurückgebracht und Surena bezwungen, und damit gezeigt, dass Ihr mindestens ebenso begabt seid wie sie es war.\n\nNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.\n\nIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.", objectives = "Beschwört mit Hilfe des Blutsteinhalsschmucks einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsschmuck zu Gakin dem Dunkelbinder in Stormwind zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1690] = { title = "Wüstenläufergerechtigkeit", description = "Ihr da! Für Euch ist es an der Zeit, ein großer Helfer der Gadgetzan Water Company zu sein.\n\nDie Wüstenläufernomaden draußen in der Tanariswüste haben fast alle Wasserbrunnen erobert! Ohne Zugang zu den Brunnen wird unser Wasservorrat im Handumdrehen schwinden. Wenn Ihr Euch unsere Dankbarkeit verdienen wollt, dann helft uns, diese Nomaden der Gerechtigkeit zuzuführen!\n\nBegebt Euch von hier Richtung Osten und schaltet zehn Banditen und Diebe der Wüstenläufer aus und meldet Euch dann umgehend wieder bei mir. Gerechtigkeit wartet auf keinen Mann ... keinen Goblin ... ach, legt einfach los!", objectives = "Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgewhizzle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1691] = { title = "Noch mehr Wüstenläufergerechtigkeit", description = "Wir müssen uns jetzt die stärkeren Ränge der Wüstenläufernomaden vornehmen. Ihr habt bisher gute Arbeit geleistet, aber wenn wir diese Wasserbrunnen zurückerobern wollen, dann wäre es gut, wenn uns dabei so wenig Nomaden wie möglich gegenüberstünden!\n\nDieses Mal müsst Ihr ihre Schurken, Auftragsmörder und Schattenmagier erledigen. Ihr werdet sie östlich und südöstlich von hier finden.\n\nIch werde Euch nichts vormachen - das ist eine schlimme Bande. Tut dies für uns, dann sind wir auf dem besten Weg, uns das zurückzuholen, was rechtmäßig uns gehört!", objectives = "Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgewhizzle in Gadgetzan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1692] = { title = "Schmied Mathiel", description = "Ich habe das Elunit, das Ihr gesammelt habt, in eine Kiste gelegt. Bringt sie zum Schmied Mathiel, er wird eine Elunitwaffe für Euch anfertigen.\n\nMathiel ist im Süden, an der anderen Seite dieses Gebäudes zu finden.", objectives = "Bringt das Behältnis mit Elunit zu Schmied Mathiel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1693] = { title = "Waffen aus Elunit", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1698] = { title = "Yorus Gerstenbräu", description = "Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet. Er wartet im Gasthaus von Seenhain im Rotkammgebirge und verspricht jedem, der seine Prüfung besteht, eine hohe Belohnung.", objectives = "Sprecht mit Yorus Gerstenbräu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1699] = { title = "Der Rethban-Spießrutenlauf", description = "Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...\n\nIhr müsst binnen einer Stunde zurück sein.\n\nGanze Heerscharen von Rotkammgnollen versperren den Weg.\n\nVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!\n\nWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?", objectives = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.\n\nIhr dürft nicht sterben und Euren Geist befreien.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1700] = { title = "Grimand Elmore", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zu Grimand Elmore geschickt werden. Er ist hier im Zwergendistrikt, im Waffenladen.\n\nUnd duckt Euch, wenn Ihr ihm die gebt. Er bildet sich ungeheuer viel auf seine Fertigkeiten ein. Es wird ihm nicht gefallen, etwas von mir zu lernen ...", objectives = "Bringt Furens Notizen zu Grimand Elmore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1701] = { title = "Feuergehärteter Panzer", description = "Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstung herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.\n\nWas sagt Ihr dazu, $N? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.", objectives = "Sammelt die Materialien, die Furen Longbeard benötigt, und bringt sie zu ihm nach Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1702] = { title = "Der Schildschmied", description = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, $N. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...\n\nAber sie ist in Stormwind.\n\nSprecht mit meinem Freund Furen Longbeard im Zwergendistrikt von Stormwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.\n\nHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.", objectives = "Bringt das Fässlein mit Gerstenbräu zu Furen Longbeard.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1703] = { title = "Mathiel", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zum Schmied Mathiel geschickt werden. Er lebt in Darnassus. Das ist weit weg, aber ich bin sicher, er wird dankbar sein, wenn er erfährt, was ich gelernt habe.", objectives = "Bringt Furens Notizen zu Mathiel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1704] = { title = "Klockmort Spannersplint", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte, und brauche jemanden, der sie zu Klockmort Spannerspan bringt. Er ist ein Gnomen-Schmied in Ironforge, und wenn er herausfindet, was ich herausgefunden habe ... Ich wette, er reißt sich vor Aufregung selbst den Bart aus.", objectives = "Bringt Furens Notizen zu Klockmort Spannerspan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1705] = { title = "Brennendes Blut", description = "Ich gebe nur ungern zu, dass Furen tatsächlich etwas gefunden haben könnte. Aber um ganz sicher zu sein, muss ich seine Techniken an einem neuen Rüstungsteil erproben. Wenn Ihr mir mit den Materialien helft, $N, könnt Ihr die Rüstung haben.\n\nUm die Rüstung herzustellen benötige ich Proben von brennendem Blut und brennendem Felsen.\n\nDie findet man meines Wissens nur im Dämmerwald. Die Worgs der Nachtheuler in der Mine von Rolands Verdammnis haben brennendes Blut, und Gutspill, ihr Anführer, wird den Fels haben.\n\nMöge das Schicksal Euch Schnelligkeit gewähren $N.", objectives = "Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1706] = { title = "Grimands Rüstung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1707] = { title = "Wasserbeutelkopfgeld", description = "Seid gegrüßt, $n, mein Name ist Luglunket, und wir haben einen wichtigen Auftrag für Euch, wenn Ihr bereit seid! Hussah!\n\nNichts würde mir als altgedientem Leitungshahnmaschinisten mehr gefallen, als Euch jeden Wasserbeutel eines Wüstenläufers abzunehmen, den Ihr draußen in der Wüste findet. Das ist ja ohnehin unser Wasser - die Nomaden haben es einfach nur gestohlen! Die Gadgetzan Water Company bietet Euch ein offizielles Care-Paket für jeweils fünf, die Ihr abliefert. Am wichtigsten ist aber, dass Ihr Gadgetzan selbst helft!", objectives = "Bringt Leitungshahnmaschinist Luglunket in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1708] = { title = "Eisenkoralle", description = "Ich möchte Furen Longbeards neue Techniken an einer eigenen Rüstung erproben. Und weil Ihr Furen geholfen habt und er mir, sollt Ihr die Rüstung bekommen, wenn sie fertig ist!\n\nUm das Teil zu beenden, brauche ich eine spezielle Koralle, Sengkoralle. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im Sumpfland.\n\nBringt mir genügend Sengkoralle und ich mache mich gleich an die Arbeit. Und beeilt Euch, $N. Ich brenne so sehr darauf, endlich anzufangen, dass meine Zehen jucken!", objectives = "Bringt 20 Ladungen Sengkoralle zu Klockmort Spannerspan in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1709] = { title = "Klockmorts Kreation", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1710] = { title = "Sonnenverbrannte Schalen", description = "Mein Kollege, Furen Longbeard, hat eine Entdeckung gemacht, die ich schnellstens ausprobieren möchte. Ich möchte sie an einer neuen Rüstung erproben, an der ich forsche, denn ich glaube, Furens Techniken werden grandiose Ergebnisse erzielen.\n\nWerdet Ihr mir helfen? Wenn Ihr sammelt, was ich zur Herstellung der Rüstung brauche, fertige ich für Euch auch eine an.\n\nIch brauche sonnenverbrannte Eierschalen der Steilhangflügeldrachen, die am Steilhang in Tausend Nadeln hausen. Sucht unter den Nestern nach den Schalen und kommt zu mir zurück, wenn Ihr eine ausreichende Menge habt.", objectives = "Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1711] = { title = "Mathiels Rüstung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1712] = { title = "Cyclonian", description = "Ich beobachte diesen Ort seit Ewigkeiten. Ich beobachte, damit ich eines Tages den großen Cyclonian fallen sehen kann. Doch ich fand noch keinen Helden, der den Windlord besiegen konnte.\n\nVielleicht seid Ihr dieser Held.\n\nBeweist es mir. Sammelt die Gegenstände, die ich brauche, um Cyclonian zu beschwören, dann weiß ich, dass Ihr ein großer Krieger seid. Vielleicht könnt Ihr ihn besiegen und sein Wirbelherz bekommen.\n\nWenn ja, übertrage ich die Macht des Herzens in eine Waffe und schenke Euch diese Waffe.\n\nHier ein Pergament mit den Gegenständen, die ich benötige.", objectives = "Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1713] = { title = "Die Beschwörung", description = "Ich bin bereit, das Ritual zur Beschwörung Cyclonians durchzuführen. Wenn er beschworen ist, müsst Ihr ihn besiegen und sein Wirbelherz nehmen. Ich werde es benutzen, um eine Waffe mit Cyclonians Macht zu stärken.\n\n$n, seid Ihr bereit, dem Windlord zu trotzen?", objectives = "Bringt das Wirbelherz zu Bath'rah dem Windbehüter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1714] = { title = "Essenz der Verbannung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1715] = { title = "Zum Geschlachteten Lamm", description = "Hmph. Früher wurden alle Hexenmeister in Khaz Modan unter der Aufsicht der Meister von Gnomeregan ausgebildet, doch jetzt, wo wir gezwungen wurden, in dieses Rattenloch in Ironforge zu ziehen und Magni beschloss, uns genau zu beobachten, sind wir gezwungen, unsere Novizen zur Ausbildung nach Stormwind zu schicken.\n\nZum Glück ist Gakin kein Tölpel, daher werdet Ihr lernen, was Ihr wissen müsst. Dennoch bringt es mein Blut zum Kochen!\n\nWie auch immer, Ihr findet Gakin im Keller des Geschlachteten Lamms in Stormwind.", objectives = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1716] = { title = "Verschlinger der Seelen", description = "Ein Sukkubus ist ein Verschlinger der Seelen, Zerstörer der Herzen, Bezwinger des Geistes. Er kennt nur das Böse.\n\nDies ist die Kreatur, die Ihr beschwören und beherrschen lernt, doch ohne Anreiz kann sie nicht in unsere Welt gebracht werden.\n\nMit einem Symbol der Liebe als Köder wird er gewiss auf Euren Ruf reagieren. Dann könnt Ihr ihn besiegen und zu Eurem Werkzeug machen.\n\nEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.", objectives = "Sprecht mit Takar dem Seher im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1717] = { title = "Gakins Beschwörung", description = "$n! Ich hätte nicht erwartet, Euch in der Gegend zu sehen, wurde aber angewiesen, nach Euch Ausschau zu halten.\n\nHöchste Zeit, dass Eure Ausbildung fortgesetzt wird. Beim nächsten Besuch in Stormwind solltet Ihr bei Gakin reinschauen. Er wird Euch erwarten.", objectives = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1718] = { title = "Der Inselbewohner", description = "Euer Ruf als Krieger wächst, $N. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.\n\nVor der Küste des Brachlandes, südlich von Ratchet, liegt eine Insel. Sie heißt Prügel-Eiland und ist ein Treffpunkt für Krieger.\n\nGeht dorthin und kämpft.\n\nSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.\n\nUm die Prügel-Eiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.", objectives = "Sprecht mit Klannoc Macleod.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1719] = { title = "Der Ringkampf", description = "Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügel-Eiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.\n\nGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flathead, dass Ihr bereit seid, und er schickt Euch Herausforderer.\n\nWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.", objectives = "Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügel-Eiland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1738] = { title = "Herzholz", description = "Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.\n\nIm Krieg der Urtume fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.\n\nEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes von Ashenvale.", objectives = "Holt das Herzholz aus Ashenvale und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1739] = { title = "Die Bindung", description = "Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.\n\nSeid vorsichtig, $n, Sukkubi haben schon den stärksten Geist unterjocht.\n\nWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.", objectives = "Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1740] = { title = "Die Kugel von Soran'ruk", description = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.\n\nViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.\n\nDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolyten der Twilight-Hammer in der Blackfathom-Tiefe benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Shadowfang. Sucht sie, dann kann ich sie zusammenfügen...", objectives = "Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1758] = { title = "Foliant der Kabale", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolyten und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Krom Stoutarm Euch dabei helfen. Heute ist er ein fahrender Hexenmeister, hortet alte Schriften und hängt in der Bibliothek von Ironforge herum.", objectives = "Sprecht mit Krom Stoutarm in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1778] = { title = "Der Foliant der Offenbarung", description = "Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Stormwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, $C.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1779] = { title = "Der Foliant der Offenbarung", description = "Ich möchte, dass Ihr das nehmt, $n. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.\n\nMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.\n\nNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.", objectives = "Nehmt das Symbol des Lebens und sprecht mit Muiredon Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1780] = { title = "Der Foliant der Offenbarung", description = "Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, $C. Es kommt nicht oft vor, dass $GMänner:Frauen; Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Stormwind die Bedürftigen nicht im Stich lassen.\n\nLebt wohl.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1781] = { title = "Der Foliant der Offenbarung", description = "Nehmt das, $n. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.\n\nMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.\n\nNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.", objectives = "Bringt das Symbol des Lebens zu Gazin Tenorm in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1782] = { title = "Furens Rüstung", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1783] = { title = "Der Foliant der Offenbarung", description = "Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbedsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.\n\nNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.\n\nNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.\n\nKönnt Ihr helfen, $N?", objectives = "Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1784] = { title = "Der Foliant der Offenbarung", description = "Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Captain ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.\n\nEinige im Rat von Ironforge glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.\n\nBeschafft eines dieser Manuskripte und bringt es zu Muiredon, $N.", objectives = "Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbedsee und kehrt zu Muiredon Battleforge in Ironforge zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1785] = { title = "Der Foliant der Offenbarung", description = "Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.\n\n's Licht soll mit Euch sein, $C. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.", objectives = "Sprecht mit Tiza Battleforge in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1786] = { title = "Der Foliant der Offenbarung", description = "Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.\n\nAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.\n\nHenze wehrte sie ab, derweil ich entkam ... der elende Narr muss immer den Helden spielen.\n\nEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, $N?", objectives = "Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1787] = { title = "Der Foliant der Offenbarung", description = "Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.\n\nMomentan bin ich nicht in der Verfassung zu kämpfen, $n. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?\n\nWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.", objectives = "Beschafft ein Manuskript der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Stormwind zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1788] = { title = "Der Foliant der Offenbarung", description = "Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!\n\nNochmals danke, $n. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.", objectives = "Sprecht mit Duthorian Rall in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1789] = { title = "Das Symbol des Lebens", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1790] = { title = "Das Symbol des Lebens", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1791] = { title = "Der Windbehüter", description = "Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.\n\nSprecht mit Bath'rah dem Windbehüter. Das ist ein Troll-Einsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.\n\nUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.", objectives = "Sprecht mit Bath'rah dem Windbehüter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1792] = { title = "Wirbelwaffe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1793] = { title = "Der Foliant der Ehre", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1794] = { title = "Der Foliant der Ehre", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1795] = { title = "Die Bindung", description = "Wenn Ihr hinreichend vorbereitet seid, sollten wir beginnen. Lasst mich Euch den Vorgang erklären.\n\nIch beginne damit, dass ich den Standard-Beschwörungskreis erstelle. Wenn das geschehen ist, werden meine Akolyten mit den Kanalisierungsruten den größeren Kreis erstellen.\n\nIst das abgeschlossen, lest Ihr die Zauberformel aus dem Folianten der Kabale und der Teufelsjäger erscheint. Seid vorsichtig, $n. Ein Teufelsjäger ist ein mächtiger Widersacher. Ich möchte nicht, dass er Euch einen Kopf kürzer macht.", objectives = "Beschwört mit Hilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratchet zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1796] = { title = "Komponenten für die verzauberte Goldblutrobe", description = "Der erste Gegenstand, bei dessen Erschaffung ich Euch helfen werde, ist eine Robe. Ihr werdet die Gegenstände für mich sammeln und wir werden sie zusammensetzen. Vorausgesetzt Ihr seid erfolgreich, werdet Ihr danach den ersten von vielen Gegenständen haben, die Euch mächtiger machen und Euch bei Eurem Kampf helfen werden.\n\nFür den Anfang müsst Ihr in den Besitz der Roben von Arcana kommen. Ein Schneider kann sie für Euch machen oder vielleicht könnt Ihr eine von jemandem kaufen... am meisten würde es mich beeindrucken, wenn Ihr sie selbst herstellen könntet... aber wie auch immer, bringt mir die Roben und dann machen wir weiter.", objectives = "Bringt die Roben von Arcana zu Menara Voidrender im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1798] = { title = "Die Suche nach Strahad", description = "Es ist Zeit, dass Ihr die Beschwörung eines Teufelsjägers lernt, $n. Ich habe nicht die erforderlichen Reagenzien und Gegenstände, um Euch hier zu unterrichten, daher müsst Ihr einen anderen aus unserem inneren Kreis aufsuchen, nämlich Strahad Farsan.\n\nEr hat sich im Goblin-Hafen von Ratchet niedergelassen. Ich werde ihn von Eurer Ankunft in Kenntnis setzen lassen.", objectives = "Sprecht mit Strahad Farsan im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1799] = { title = "Fragmente der Kugel von Orahil", description = "Gut, dann können wir beginnen.\n\nIhr müsst als Erstes mit meinen Akolyten im Inneren sprechen. Wählt einen ihrer Wege und folgt ihm - sie werden Euch alles erklären.\n\nAls Zweites müsst Ihr nach Desolace reisen und eine Höllenkugel von einem der Hexenmeister von Mannorocs Koven holen. Diese Kugel werdet Ihr mit der Hilfe einer Magierin namens Tabetha tief in den südlichen Marschen von Dustwallow reinigen. Sie wird Euch aufgrund unserer gemeinsamen Vergangenheit helfen.\n\nKommt erst zurück, wenn Ihr beide Dinge erledigt habt, um die ich Euch gebeten habe.", objectives = "Sprecht mit Menaras Akolyten im Inneren des Turms über Ratchet und wählt einen ihrer Wege, um ihm zu folgen.\n\nBringt danach eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1800] = { title = "Der Thronsaal von Lordaeron", description = "Wenn wir brav sind und die Hausarbeiten ordentlich machen, erzählen uns die Waisenmatronen oft Geschichten von großen Schlachten und darüber, wie Lordaeron fiel und wie der böse Arthas seinen eigenen Vater umbrachte, nur um König zu werden.\n\nEr hatte keine Ehre, $n! Wenn ich erst einmal groß und ein mächtiger Krieger der Horde bin, wird mein Schwert durch die Ehre geleitet werden; niemals durch das Böse!\n\nWürdet Ihr mit mir den Thronsaal besuchen, bitte? Er befindet sich kurz vor dem Abgang, über den man nach Unterstadt heruntergeht.", objectives = "Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Unterstadt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1801] = { title = "Foliant der Kabale", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolyten und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Jorah Annison Euch dabei helfen. Heute arbeitet er als Kartograf in Undercity, weiß aber dennoch mehr über alte Schriften als ich.", objectives = "Sprecht mit Jorah Annison in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1802] = { title = "Foliant der Kabale", description = "Er ist verschollen, aber man glaubt zu wissen, wo man ihn finden könnte.\n\nNur eine Kopie wurde jemals angefertigt, und die wurde einst beschädigt, eine Vielzahl von Seiten herausgerissen. Man munkelt, dass er irgendwie den Zentauren von Tausend Nadeln in die Hände gefallen sein soll.\n\nDer Rest ging an der Küste westlich von Southshore verloren, als er per Schiff zum Hafen von Menethil hätte transportiert werden sollen. Er kam nie an.\n\nAls Gegenleistung für dieses Wissen verlange ich nur, dass Ihr ihn findet und mir zur Ansicht bringt.", objectives = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Stoutarm in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1803] = { title = "Foliant der Kabale", description = "Ah! Ich sehe, Ihr seid ein Hexenmeister, der meinen Geschmack teilt. Den Folianten der Kabale zu beschaffen ist ein würdiges Ziel. Habt Ihr gewusst, dass er sich einst innerhalb der Mauern von Lordaeron befand? Aber er wurde beschädigt, fast die Hälfte der Seiten herausgerissen. Wer würde so eine abscheuliche Tat begehen?\n\nDiese Hälfte ist verschollen, doch man munkelt, sie soll den Zentauren von Tausend Nadeln in die Hände gefallen sein.\n\nDer Rest des Textes sollte nach Ironforge gebracht werden, ging aber während der Überfahrt an der Westküste von Southshore verloren.", objectives = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1804] = { title = "Foliant der Kabale", description = "Ach ja, es ist recht schwer, ihn aus der Hand zu geben. Aber Ihr habt ihn gefunden und natürlich Wichtigeres damit zu tun. Vergesst nur nicht, Strahad zu sagen, dass ich eine Kopie haben möchte.\n\nWährend Ihr fort wart, hat er eine Nachricht für Euch geschickt. Er sagte mir, damit seine Akolyten bei der Beschwörung helfen können, müsst Ihr drei Kanalisierungsruten beschaffen.\n\nEr weiß vielleicht nicht, wo man die findet, aber ich! Sie wurden zuletzt von den Orcs des Dragonmawklans im Sumpfland verwendet. Ich würde mich mal mit ihren Zauberern in Verbindung setzen!", objectives = "Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1805] = { title = "Foliant der Kabale", description = "Das ist einer der interessantesten Texte, die ich in den letzten Jahren gelesen habe. Die Auswahl hier ist nicht sonderlich groß - zum Großteil sind es Bücher über Geographie - und ich habe sie schon alle gelesen. Hoffentlich schickt mir Strahad eine Kopie dieses Folianten, wenn er die Chance dazu hat.\n\nDa wir gerade von ihm sprechen: während Ihr fort wart, habe ich eine Nachricht von ihm erhalten. Für Eure Aufgabe müsst Ihr drei Ruten des Kanalisierens beschaffen.\n\nWeil Ihr mir diesen Text gezeigt habt, weihe ich Euch in ein Geheimnis ein: Ihr findet die Ruten bei den Orcs des Dragonmawklans im Sumpfland.", objectives = "Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1806] = { title = "Die Prüfung der Rechtschaffenheit", description = "Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.\n\nWenn wir fertig sind, werdet Ihr viel besser gerüstet sein, das Licht zu verteidigen, als bisher, das schwöre ich Euch.\n\nIch will ehrlich sein, $n, wenn ich die Ergebnisse Eurer Taten sehe, erfüllt mich ein gewisser Neid. Doch das Wissen, dass ich auf meine bedeutende Weise zu Euren Abenteuern beitragen kann, erfüllt mich mit Freude.", objectives = "Wartet, bis Jordan Stilwell eine Waffe für Euch geschmiedet hat.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1818] = { title = "Gespräch mit Dillinger", description = "Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der Dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.\n\nTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.", objectives = "Sprecht mit Todeswache Dillinger in Brill.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1819] = { title = "Ulag der Spalter", description = "Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.\n\nWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. \n\nBefreit und tötet ihn.\n\nAktiviert den Schädelstein-Auslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.\n\nUnd dann... seid bereit, $N.", objectives = "Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1820] = { title = "Gespräch mit Coleman", description = "Ihr habt Euren Wert für die dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.\n\nColeman Farthing wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.\n\nIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.", objectives = "Sprecht mit Coleman Farthing.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1821] = { title = "Agamand-Erbstücke", description = "Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.\n\nUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!\n\nDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.", objectives = "Bringt Coleman Farthing die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1822] = { title = "Erbstückwaffe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1823] = { title = "Gespräch mit Ruga", description = "Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Ragetotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.\n\nEr wartet auf Krieger, die seinem Ruf folgen.", objectives = "Sprecht mit Ruga Ragetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1824] = { title = "Prüfung auf dem Feld der Riesen", description = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.\n\nBringt mir einen ihrer noch zuckenden Fühler und vergeudet keine Zeit, $N, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.", objectives = "Bringt 5 zuckende Fühler zu Ruga Ragetotem im Camp Taurajo.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1825] = { title = "Gespräch mit Thun'grim", description = "Thun'grim Firegaze, ein berühmter Orc-Schmied, hat von Euren fortgesetzten Heldentaten im Dienst der Horde gehört. Er möchte eine Rüstung für Euch anfertigen und bittet, dass Ihr umgehend mit ihm sprecht.\n\nThun'grims Lager liegt östlich von Crossroads im Brachland.", objectives = "Sprecht mit Thun'grim Firegaze im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1838] = { title = "Brutale Rüstung", description = "Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.\n\nAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, $n. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.\n\nHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.", objectives = "Bringt Thun'grim Firegaze 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1839] = { title = "Ula'elek und die brutalen Stulpen", description = "Der Trollschmied Ula'elek wird die brutalen Stulpen für Euch anfertigen. Er wohnt mit seinen Darkspearbrüdern in Durotar in Sen'jin und erwartet Eure Ankunft.", objectives = "Sprecht mit Ula'elek in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1840] = { title = "Orm Stonehoof und der brutale Helm", description = "Orm Stonehoof wird ob seiner Fertigkeiten hoch geachtet. Er wird den brutalen Helm für Euch machen.\n\nSucht ihn in Thunder Bluff beim Teich nahe dem großen, zentralen Totem der Stadt.", objectives = "Sprecht mit Orm Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1841] = { title = "Velora Nitely und die brutalen Beinschützer", description = "Es heißt, vor ihrem Tod hätte Velora Nitely zu den besten Rüstungsschmieden von Lordaeron gehört. Offenbar konnte der Tod ihrem Talent nichts anhaben. Sprecht mit Velora - sie wird die brutalen Beinschützer für Euch machen.\n\nVelora geht ihrem Gewerbe in Undercity unterhalb von Lordaeron nach, im Handwerksviertel.", objectives = "Sprecht in Undercity mit Velora Nitely.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1842] = { title = "Satyrhufe", description = "Ich kann Euch ein Paar brutale Stulpen machen, denen große Magie innewohnen wird. Doch vorher müsst Ihr diese Magie sammeln und mir bringen.\n\nDie Satyrn halten sich im nordöstlichen Teil von Ashenvale auf wegen der Macht, die dem Wald innewohnt. Sie nähren sich an seiner Reinheit, saugen sie ab und verderben sie. An den geschwollenen, ungespaltenen Hufen erkennt man, welche Satyrn die meiste Magie Ashenvales aufgenommen haben.\n\nDiese Hufe besitzen große Macht. Ich brauche sie, um Eure Stulpen anzufertigen.", objectives = "Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1843] = { title = "Brutale Stulpen", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1844] = { title = "Schimärenhorn", description = "Ich mache Euch den Helm, doch vorher müsst Ihr mir zeigen, dass Ihr würdig seid.\n\nEingebettet in die nordwestlichen Ausläufer des Steinkrallengebirges liegt das verbrannte Tal. Das war einst ein fruchtbarer Ort, ist aber heute besudelt und voll Asche. Die Kreaturen, die dort noch hausen, sind wahnsinnig vor Schmerz und Verzweiflung.\n\nAn diesen Ort schicke ich Euch, $N.\n\nIhr müsst zum verbrannten Tal reisen und eine Schimärenmatriarchin suchen. Tötet sie, erlöst sie von ihrem Elend. Bringt mir ihr galvanisiertes Horn als Beweis, dann mache ich den Helm für Euch.", objectives = "Bringt ein galvanisiertes Horn zu Orm Stonehoof in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1845] = { title = "Brutaler Helm", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1846] = { title = "Schienbeinknochen der Dragonmaw", description = "Um brutale Beinschützer zu machen, brauche ich eine Stütze aus stabilem Schienbeinknochen. Die Orcs des Dragonmawklans im Sumpfland haben hübsche, dicke Schienbeinknochen. Die brauche ich.\n\nAber sie müssen stabil sein. Prüft die Schienbeinknochen unbedingt, wenn Ihr sie einsammelt. Wenn Ihr sie mit bloßen Händen zerbrechen könnt, sind sie nicht stabil genug für mich.", objectives = "Bringt 8 stabile Schienbeinknochen eines Dragonmaw zu Velora Nitely in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1847] = { title = "Brutale Beinschützer", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1848] = { title = "Brutale Halsberge", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1858] = { title = "Die Shattered-Hand", description = "Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.\n\nDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.", objectives = "Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1859] = { title = "Therzok", description = "Sprecht leiser, $n. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.\n\nSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.\n\nHabe ich Recht?\n\nWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.", objectives = "Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1860] = { title = "Gespräch mit Jennea", description = "Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Stormwind und dem Wald von Elwynn von entscheidender Bedeutung.\n\nJennea Cannon kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Stormwind. Ihr solltet Euch eiligst zu ihr begeben.", objectives = "Sprecht in Stormwind mit Jennea Cannon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1861] = { title = "Spiegelsee", description = "Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden. Einige von uns fürchten das Schlimmste.\n\nAber davon werde ich Euch später mehr erzählen. Im Augenblick müsst Ihr Informationen für uns sammeln.\n\nHier, nehmt dieses Fläschchen. Geht zum Wasserfall des Spiegelsees, südwestlich der Tore von Stormwind, und holt dort eine Probe des Wassers. Bringt sie mir, damit ich die magische Besudelung messen kann.", objectives = "Bringt eine Probe des Spiegelsee-Wassers zu Jennea Cannon in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1878] = { title = "Wasserbeutelkopfgeld", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1879] = { title = "Gespräch mit Bink", description = "$N! Bink, meine Gnomen-Kollegin in Ironforge, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr $gein Magier:eine Magierin;, $N?\n\nWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Ironforge in der Halle der Mysterien im mystischen Krieg.", objectives = "Sprecht mit Bink in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1880] = { title = "Magitastischer Gizmonitor", description = "Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit. Und Wissen... viel, viel Wissen!\n\nEines meiner Geräte, der magitastische Gizmonitor, sammelt und speichert dieses Wissen in riesigen Mengen! Aber ich verlor ihn! Als wir aus unserer Heimat Gnomeregan flohen, ließ ich ihn in einer Truhe in einer unserer Hütten vor der Stadt, und jetzt wimmelt es dort von Lepragnomen!\n\nBitte, $n, findet meinen Gizmonitor wieder!", objectives = "Bringt Bink ihren magitastischen Gizmonitor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1881] = { title = "Gespräch mit Anastasia", description = "$N, Anastasia Hartwell hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Undercity und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.", objectives = "Sprecht mit Anastasia Hartwell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1882] = { title = "Balnirs Bauernhof", description = "Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verdirbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.\n\nDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen - Löwenmäulchen. Sammelt sie und kehrt zurück.", objectives = "Bringt Balnir-Löwenmäulchen zu Anastasia Hartwell im Magierviertel von Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1883] = { title = "Gespräch mit Un'thuwa", description = "Un'thuwa, Stammesmagier in Sen'jin, spürt eine Störung in den magischen Strömen von Durotar und bittet um Unterstützung. Sprecht mit Un'thuwa und tut, was Ihr könnt, um ihm zu helfen.\n\nGelingt Euch das, werden Euch zu gegebener Zeit weitere Geheimnisse enthüllt.", objectives = "Sprecht mit Un'thuwa.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1884] = { title = "Jujuhaufen", description = "Der Hexenmeister Zalazane von den Echoinseln hat den normalen Fluss der Magie in Durotar gestört. Das vollbringt er mit besudelten Fetischen, Jujuhaufen, die er auf der Echohauptinsel in seinen Hütten aufgeschichtet hat.\n\nDiese Haufen haben unser Ökosystem verdorben und Hexenmeistern und Höllenkreaturen, die in den dunklen Winkeln des Landes hausen, Macht gegeben.\n\nIhr müsst diese Jujuhaufen zerstören, $n, bevor der Fluss der Magie für immer verändert ist.", objectives = "Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1885] = { title = "Mennet Carkad", description = "$n? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?\n\nSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.", objectives = "Sprecht mit Mennet Carkad im Schurkenviertel von Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1886] = { title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, $N, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Undercity pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", objectives = "Beschafft Astors Empfehlungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1898] = { title = "Die Todespirscher", description = "Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteil werden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", objectives = "Sprecht mit Andron Gant in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1899] = { title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", objectives = "Bringt Astors Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1918] = { title = "Das beschmutzte Element", description = "Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass, was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.\n\nEs ist nicht gerade weit bekannt, wer sich für solch einen Fund interessieren könnte. Vielleicht weiß die Person etwas darüber, die Euch ursprünglich zum See hinausgeschickt hatte - Mastok Wrilehiss im Splintertreeposten.", objectives = "Bringt die beschmutzte Wasserkugel zu Mastok Wrilehiss im Splintertreeposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1919] = { title = "Meldung bei Jennea", description = "Euer Wissen über das Handwerk wächst, $N. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?\n\nWenn ja, sprecht mit Jennea Cannon im Magiersanktum im Magierviertel von Stormwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.", objectives = "Sprecht in Stormwind mit Jennea Cannon.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1920] = { title = "Untersuchungen im Blauen Eremiten", description = "Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.\n\nIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", objectives = "Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1921] = { title = "Materialsammlung", description = "Ihr habt Euren Magierkollegen gut gedient, jetzt wird es Zeit, die Hexerrobe anzuziehen. Wynne Larson kann Eure Robe nähen, aber Ihr müsst ihr die erforderlichen Materialien bringen. \n\nEure Robe wird aus Leinen bestehen, das leicht zu beschaffen ist, aber Ihr müsst auch aufgeladene Rissedelsteine finden, die nur in der Silberbachmine vom Loch Modan zu finden sind, wo die Minenarbeiterliga der Zwerge sie in Kisten zurückgelassen hat.\n\nBeschafft das Leinen und die Edelsteine und bringt sie zu Wynne Larson in das Konfektionsgeschäft Larson im Magierviertel.", objectives = "Bringt 10 Leinentücher und 6 aufgeladene Rissedelsteine zu Wynne Larson in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1938] = { title = "Urs Abhandlung über Schattenmagie", description = "Vor langer Zeit studierten drei Magier in diesem Turm, bis einer den dunklen Künsten verfiel. Man bedrängte ihn, von dieser bösen Magie zu lassen, aber er konnte nicht widerstehen. Und so wurde er verbannt.\n\nDas neue Domizil des gefallenen Magiers ist der Turm von Ilgalar im Rotkammgebirge. Er hat ein mächtiges Buch dorthin mitgenommen -'Urs Abhandlung über Schattenmagie'.\n\nWir, die Magier von Stormwind, möchten dieses Buch zurück. Begebt Euch in den Turm von Ilgalar, sucht den Folianten in seiner Bibliothek und bringt ihn mir.", objectives = "Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1939] = { title = "Zaubermeister Andromath", description = "Der Zaubermeister Andromath wünscht Euch zu sprechen, $N. Er ist oben im Magiersanktum im Magierviertel von Stormwind.\n\nEs wäre klug, mit ihm zu sprechen, denn Andromath ist einer der mächtigsten Magier, die nicht in Dalaran eingesperrt sind. Ein Rat von ihm ist in jedem Fall ein guter Rat.", objectives = "Sprecht mit Zaubermeister Andromath.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1940] = { title = "Makellose Spinnenseide", description = "Eure Treue ist unerschütterlich, $n. Ich glaube, es ist an der Zeit, dass Ihr ein besseres Kleidungsstück bekommt, das einem geschickten Magier von Eurem Rang angemessener ist. Wenn Ihr die erforderlichen Materialien sammeln könnt, werde ich veranlassen, dass die Robe angefertigt wird.\n\nIhr müsst in den Dämmerwald und Aaskrabblerspinnen jagen. Extrahiert ihre Seide, aber nur die feinste und makelloseste. Wenn Ihr genug davon habt, bringt sie zu Wynne Larson ins Konfektionsgeschäft Larson hier im Magierviertel. Sie wird Eure Robe anfertigen.", objectives = "Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Stormwind.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1941] = { title = "Managewirkte Robe", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1942] = { title = "Astralknotengewand", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1943] = { title = "Gespräch mit Deino", description = "Die Trollmagierin Deino bedarf Eurer Unterstützung, $N. Sie residiert in Orgrimmar im Dunkeldornen-Lodge.", objectives = "Sprecht mit Deino.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1944] = { title = "Wasser von Xavian", description = "Die legendäre Stadt Xavian liegt tief im östlichen Ashenvale. Die Geschichten über ihr Wissen aus längst vergangener Zeit sind den Gebildeten wohl bekannt. Man sagt, die Wasser von Xavian bergen enorme magische Kräfte.\n\nBringt mir eine Probe dieses Wassers direkt von der Quelle.\n\nNehmt dieses Fläschchen und reist nach Xavian. Füllt Wasser am höchsten Wasserfall ab und kehrt zu mir zurück. Aber seid vorsichtig in der uralten Stadt - heute hausen Satyrn in den Ruinen, die gar nicht mögen, wenn sich Magier in ihre Angelegenheiten einmischen.", objectives = "Bringt die Probe des Wassers von Xavian zu Deino in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1945] = { title = "Lachende Schwestern", description = "Als Dank für Eure Dienste habe ich veranlasst, dass Euch neue Roben angefertigt werden, sofern Ihr die erforderlichen Materialien beschaffen könnt...\n\nFür diese Roben müsst Ihr nach Ashenvale zurückkehren und Locken vom Haar der lachenden Schwestern beschaffen - Dryaden, die sich in der Nähe des Raynewoodes tummeln.\n\nWenn Ihr das Haar habt, bringt es zu Kil'hala, einem Trollschneider in Crossroads im Brachland. Er wird Euch erwarten und Eure Roben zuschneiden.", objectives = "Bringt 12 Haarlocken der lachenden Schwestern zu Kil'hala in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1946] = { title = "Netherspitzengewand", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1947] = { title = "Reise in die Marschen", description = "Jetzt ist es an der Zeit, Euch Euren Magierzauberstab zu verdienen. Um diese Aufgabe zu beginnen, solltet Ihr mit der Menschen-Einsiedlerin Tabetha in den Marschen von Dustwallow sprechen. Ihr findet ihre Hütte tief in den Marschen, westlich von Theramore.\n\nSprecht mit ihr, denn sie verfügt über umfangreiches Wissen. Tabethas Hütte befindet sich westlich von Theramore und direkt nördlich der Stonemaul Ruinen.", objectives = "Sprecht mit Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1948] = { title = "Gegenstände der Macht", description = "Es ist nicht leicht, einen Magierzauberstab anzufertigen. Es sind rare Substanzen erforderlich und ein Gefäß muss gemacht werden, das große Mengen magischer Energie speichern kann. Ihr müsst diese Sachen sammeln und mir bringen.\n\nIch habe auf dieses Pergament geschrieben, was Ihr braucht und wie Ihr es bekommt. Bringt mir exakt das, was auf der Liste steht und folgt meinen schriftlichen Anweisungen auf den Buchstaben genau, denn wenn Ihr das nicht macht, geht bei der Herstellung Eures Zauberstabes vielleicht etwas ... schief.", objectives = "Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1949] = { title = "Verborgene Geheimnisse", description = "Um Euren Zauberstab herzustellen, muss ich einige wichtige Stellen in einem bestimmten Buch lesen. Dieses Buch wurde von dem Magus Tirth geschrieben und heißt 'Rituale der Macht'.\n\nIch besitze kein Exemplar dieses Buchs und es ist in keiner der großen Bibliotheken der Welt zu finden. Daher müsst Ihr mit Tirth sprechen und es von ihm bekommen.\n\nViel Glück. Tirth war ein großer Magier und Gelehrter, aber heute verbringt er seine Zeit bei den Gnomen- und Goblinrennen auf der schimmernden Ebene und trinkt und spielt.", objectives = "Sprecht mit Magus Tirth in der Schimmernden Ebene.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1950] = { title = "Der Knüller schlechthin", description = "Ich kann Euch mit dem Buch helfen, doch vorher müsst Ihr mir helfen!\n\nDer Foliant, den Ihr sucht, befindet sich in meiner magisch versiegelten Geldkassette. Um sie zu öffnen, muss ein bestimmter Satz gesprochen werden, aber ich kann mich nicht mehr an ihn erinnern! Normalerweise merkt sich mein Assistent so etwas, aber der ist unauffindbar.\n\nWenn Ihr mein Buch möchtet, sucht meinen Lehrling! Fragt auf der Rennbahn - wenn Ihr Glück habt, hat ihn jemand gesehen. Schleppt ihn entweder hierher oder entlockt ihm wenigstens meinen magischen Satz, damit wir die Kassette aufbekommen!", objectives = "Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1951] = { title = "Rituale der Macht", description = "Hm, wenn ich so darüber nachdenke, ich habe mein Buch nicht! Wisst Ihr, ich hatte Spielschulden, und um sie zu bezahlen, verkaufte ich das letzte Exemplar von 'Rituale der Macht' an ein Mitglied der Kleriker...\n\nEin Mitglied der Scharlachroten Bruderschaft. Er muss es zur Bibliothek im Scharlachroten Kloster in Tirisfal gebracht haben!\n\nWenn Ihr das Buch wollt, müsst Ihr in das Kloster gehen und es suchen. Und entschuldigt den ganzen Ärger. Ich bin neuerdings nicht mehr ich selbst...", objectives = "Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1952] = { title = "Der Zauberstab des Magiers", description = "Ich werde jetzt die Zauberstäbe machen.", objectives = "Sprecht nach ihrem Ritual mit Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1953] = { title = "Rückkehr in die Marschen", description = "$N, es wird Zeit, dass Ihr mit Tabetha sprecht... der Einsiedlerin in den Marschen von Dustwallow. Sie wird Euch in der Herstellung einer mächtigen Magiergerätschaft unterweisen.\n\nTabethas Hütte liegt tief in den Marschen von Dustwallow, westlich von Theramore.", objectives = "Sprecht mit Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1954] = { title = "Die Höllenkugel", description = "Als ersten Schritt müsst Ihr eine Kugel voll Macht beschaffen. Die Hexenmeister der Burning Blade haben hübsche, hochwertige Kugeln... zu dumm, dass sie Dämonen darin eingebunden haben! Aber das können wir ändern, ja.\n\nGeht nach Desolace und nehmt einem Beschwörer der Burning Blade eine Höllenkugel ab. Beschwörer findet Ihr bei Mannorocs Koven.\n\nKommt zu mir zurück, wenn Ihr die Kugel habt.", objectives = "Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1955] = { title = "Die Austreibung", description = "Jetzt, da wir eine Beschwörerkugel haben, müssen wir den Dämon darin austreiben. Ich kann es machen. Das ist der einfache Teil.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, wenn er draußen ist.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, springt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", objectives = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1956] = { title = "Macht in Uldaman", description = "Jetzt, nachdem der Dämon entfernt wurde, müssen wir eine Kraftquelle finden. Leider sind die besten Kraftquellen meistens die ältesten und die, an die man am schwersten rankommt. Ist schon lustig, wie einem das Schicksal manchmal mitspielt, wie?\n\nAlso müsst Ihr nach Uldaman und dort die Obsidianschildwache besiegen. Der Kerl ist groß, er ist zäh und seine Kraftquelle hat ganz schön Pep.\n\nIch wünsche Euch viel Glück, $N. Falls Ihr kein Glück haben solltet, tja... dann war es schön, Euch gekannt zu haben.", objectives = "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1957] = { title = "Manawogen", description = "Wir sind fast fertig, aber dieser letzte Schritt ist der gefährlichste, $n.\n\nIch habe die leere Beschwörerkugel und bin bereit, sie zu ermächtigen. Das machen wir, indem wir die Energie eines Manarisses anzapfen. Ich wirke einen Zauber, der vorübergehend einen Riss auftut, aus dem Kreaturen, Manawogen, herauskommen. Ihr müsst die Manawogen vernichten, damit ihre Macht freigesetzt wird, die ich dann einsammle.\n\nZerschlagt genug Manawogen, bevor sich der Riss schließt, und ich versiegle ihre gesammelte Energie in Eurer Kugel.", objectives = "Vernichtet 12 Manawogen innerhalb des Zeitlimits.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1958] = { title = "Himmlische Macht", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1959] = { title = "Meldung bei Anastasia", description = "Die Magier von Undercity haben eine magische Störung in der Stadt bemerkt und die Magier der Horde um Untersuchung gebeten.\n\nAnastasia Hartwell kann Euch mehr sagen. Sprecht mit Ihr im Magieviertel in Undercity.", objectives = "Sprecht mit Anastasia Hartwell.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1960] = { title = "Untersuchungen im Alchimistenladen", description = "Algernons Alchimistenladen im Apothekarium ist das Zentrum einer seltsamen Störung. Unsichtbare, aus reiner Magie bestehende Kreaturen halten sich in dem Laden auf - dafür muss es einen Grund geben, und den müssen wir herausfinden!\n\nUntersucht die Störung und fangt diese Kreaturen. Nehmt Euch von dort hinten eine Truhe mit Kästen und eine Rolle. Benutzt im Laden die Rolle, um die Kreaturen sichtbar zu machen, überwältigt sie mit Euren Zaubern und fangt sie dann mit einem Kasten ein. Kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", objectives = "Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1961] = { title = "Materialsammlung", description = "Jetzt ist es Zeit, Eure erste Magierrobe anzulegen, $n. Sie ist ein Zeichen Eures Ranges und ein Zeugnis für Euren Wert.\n\nUm die Robe zu bekommen, müsst Ihr Manaedelsteine von den Magiern von Dalaran im Silberwald sammeln. Ihre Überzeugungen ähneln den unseren, daher ist es ein wenig geschmacklos, sie zu töten, aber wenn sie keine Kraft haben, uns Widerstand zu leisten, verdienen sie es nicht, zu leben.\n\nBringt die Edelsteine und das Leinen zu Josef Gregorian in der Schneiderei im Magieviertel.", objectives = "Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1962] = { title = "Roben des Zauberfeuers", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1963] = { title = "Die Shattered-Hand", description = "Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln. Einst waren wir stärker, allesamt mächtige Eroberer. Diesen Stolz müssen wir zurückerlangen, und der Klan der Shattered-Hand wird dies bewerkstelligen.\n\nWir sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Eine Aufgabe müsst Ihr für mich erledigen, um Euren Wert zu beweisen.\n\nDer Troll Tazan treibt Handel mit den Piraten bei Ratchet. Er hat Informationen, die ich haben muss. Tötet ihn und bringt mir seinen Ranzen.", objectives = "Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
